enum flags { A = 1 << 3, B = A + 1, C, D = sizeof(int) * 4 };

typedef long word;

int table[] = { [A] = 1, [D + 1] = 2, [C ... D] = 3 };

int select_int(int a) {
  return _Generic(a, int: 1, word: 2, default: 3);
}

int select_type(void) {
  return _Generic(word, long: 4, char *: 5, default: 6);
}

